describe('Checkout Flow - Sequential Async Steps', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should complete checkout flow in order with sequential async steps', () => {
    // Step 1: Add item to cart
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.intercept('POST', '/api/cart/add').as('addToCart');
    cy.wait('@addToCart');

    // Step 2: Proceed to checkout
    cy.get('[data-testid="proceed-to-checkout-button"]').click();
    cy.intercept('GET', '/api/checkout/initiate').as('initiateCheckout');
    cy.wait('@initiateCheckout');

    // Step 3: Enter shipping information
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="shipping-city-input"]').type('Anytown');
    cy.get('[data-testid="shipping-state-input"]').type('CA');
    cy.get('[data-testid="shipping-zip-code-input"]').type('90210');
    cy.intercept('POST', '/api/checkout/shipping').as('setShipping');
    cy.wait('@setShipping');

    // Step 4: Enter payment information
    cy.get('[data-testid="payment-method-select"]').click();
    cy.get('[data-testid="credit-card-input"]').type('4111111111111111');
    cy.get('[data-testid="expiration-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.intercept('POST', '/api/checkout/payment').as('processPayment');
    cy.wait('@processPayment');

    // Step 5: Confirm and submit order
    cy.get('[data-testid="confirm-order-button"]').click();
    cy.intercept('POST', '/api/checkout/complete').as('completeOrder');
    cy.wait('@completeOrder');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Order completed successfully');

    // Verify order details
    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="order-id"]').should('contain', 'ORD-123456');
    cy.get('[data-testid="order-total"]').should('contain', '$100.00');
  });

  it('should handle failure in sequential async steps and display error messages', () => {
    // Step 1: Add item to cart
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.intercept('POST', '/api/cart/add').as('addToCart');
    cy.wait('@addToCart');

    // Step 2: Proceed to checkout
    cy.get('[data-testid="proceed-to-checkout-button"]').click();
    cy.intercept('GET', '/api/checkout/initiate').as('initiateCheckout');
    cy.wait('@initiateCheckout');

    // Step 3: Enter invalid shipping information
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="shipping-city-input"]').type('Invalid City');
    cy.get('[data-testid="shipping-state-input"]').type('CA');
    cy.get('[data-testid="shipping-zip-code-input"]').type('90210');
    cy.intercept('POST', '/api/checkout/shipping').as('setShipping');
    cy.wait('@setShipping');

    // Step 4: Attempt to enter payment information
    cy.get('[data-testid="payment-method-select"]').click();
    cy.get('[data-testid="credit-card-input"]').type('4111111111111111');
    cy.get('[data-testid="expiration-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.intercept('POST', '/api/checkout/payment').as('processPayment');
    cy.wait('@processPayment');

    // Step 5: Attempt to confirm and submit order
    cy.get('[data-testid="confirm-order-button"]').click();
    cy.intercept('POST', '/api/checkout/complete').as('completeOrder');
    cy.wait('@completeOrder');

    // Verify error message
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid shipping address');

    // Verify order was not completed
    cy.get('[data-testid="success-message"]').should('not.exist');
    cy.get('[data-testid="order-summary"]').should('not.be.visible');
  });
});
